mapper.select:
SELECT
FROM async_job WHERE async_job.life_cycle_state != 'DELETED'
LIMIT #{offset},#{pageSize}

mapper.update:
UPDATE
    async_job
SET async_job.job_status = #{status}
where id = #{asyncJobId}

UPDATE async_job SET async_job.job_status = #{jobStatus,javaType=io.cronx.async.task.framework.constant.AsyncJobStatus} WHERE
async_job.id in
#{item}

mapper.select:
SELECT
FROM async_job
WHERE async_job.job_status = 'FINISHED' and async_job.is_timing = 1 and async_job.next_start_time < #{currentTs};
